/* Offline four-port collective collector.
 *
 * The switch is a pure replay device: it never opens a socket and never
 * touches a NIC.  Every ingress frame is validated, classified and applied to
 * the retained window; every egress frame is built here and handed to the
 * offline emit callback.
 */

#include "collector.h"
#include "epic_clean.h"

#include <arpa/inet.h>
#include <stdlib.h>
#include <string.h>

#define HOSTS EPIC_STAR4_HOSTS
#define MASK24 0x00ffffffu
#define DATA_OPCODE 0x04
#define ACK_OPCODE 0x11
#define UDP_PORT EPIC_ROCE_UDP_PORT

/* ------------------------------------------------------------------ state */

typedef struct {
    int used;
    uint32_t p;             /* logical input sequence */
    uint8_t mask;           /* accepted source bitmap */
    uint8_t complete;       /* collective input complete */
    uint8_t *raw[HOSTS];    /* allgather: per source, broadcast: root only */
    uint32_t *agg;          /* sum based primitives: D aggregate words */
} slot_t;

struct collector {
    int primitive;
    int mode;
    int root;
    uint32_t K;             /* logical segments */
    uint32_t D;             /* vector words */
    uint32_t N;             /* retained slots */
    uint32_t start;         /* physical PSN of logical sequence zero */
    uint32_t b;             /* retired prefix */
    uint32_t occupied;      /* occupied slots */
    slot_t *slots;
    uint32_t R[HOSTS];      /* received prefixes */
    uint32_t S[HOSTS];      /* new output sent prefixes */
    uint32_t A[HOSTS];      /* downstream acknowledged prefixes */
    uint32_t U[HOSTS];      /* upstream sent prefixes */
    uint8_t repeat[HOSTS];  /* pending upstream ACK repeat request */
    uint64_t st[32];        /* certificate counters */
    epic_emit_fn emit;
    void *user;
    epic_port_t ports[HOSTS];
    uint8_t *frame;         /* egress scratch */
    uint8_t *scratch;       /* payload scratch */
    size_t frame_cap;
};

/* ------------------------------------------------------------- primitives */

static uint8_t required_mask(const collector_t *c)
{
    if (c->primitive == EPIC_PRIM_BCAST) {
        return (uint8_t)(1u << c->root);
    }
    return 0x0fu;
}

static int is_destination(const collector_t *c, int rank)
{
    switch (c->primitive) {
    case EPIC_PRIM_REDUCE:
        return rank == c->root;
    case EPIC_PRIM_BCAST:
        return rank != c->root;
    default:
        return 1;
    }
}

/* number of output records owned by one destination */
static uint32_t dest_total(const collector_t *c, int rank)
{
    (void)rank;
    switch (c->primitive) {
    case EPIC_PRIM_BARRIER:
        return 1u;
    case EPIC_PRIM_ALLGATHER:
        return 3u * c->K;
    case EPIC_PRIM_REDUCESCATTER:
        return c->K / 4u;
    default:
        return c->K;
    }
}

/* ordinal of src inside the ascending rank list with dest omitted */
static int ordinal_excluding(int dest, int src)
{
    int ordinal = 0;
    for (int r = 0; r < HOSTS; r++) {
        if (r == dest) {
            continue;
        }
        if (r == src) {
            return ordinal;
        }
        ordinal++;
    }
    return 0;
}

static int rank_from_ordinal(int dest, int ordinal)
{
    int seen = 0;
    for (int r = 0; r < HOSTS; r++) {
        if (r == dest) {
            continue;
        }
        if (seen == ordinal) {
            return r;
        }
        seen++;
    }
    return 0;
}

/* ------------------------------------------------------------------ slots */

static void slot_release(collector_t *c, slot_t *s)
{
    for (int r = 0; r < HOSTS; r++) {
        free(s->raw[r]);
        s->raw[r] = NULL;
    }
    free(s->agg);
    s->agg = NULL;
    s->used = 0;
    s->mask = 0;
    s->complete = 0;
    s->p = 0;

